import { LemniscateSwarm } from '@/components/LemniscateSwarm';

/** Lowercase brand wordmark shown next to the animated logo. */
export const BRAND_NAME = 'lemniscate';

interface BrandMarkProps {
  /**
   * Whether the lemniscate swarm travels. Defaults to true; callers pass false
   * (or the activity flag) so the mark is static when no task is running or in
   * review.
   */
  animate?: boolean;
}

/**
 * Brand lockup: animated lemniscate mark next to the lowercase wordmark.
 * The mark is boxed at 2em (twice the label font size) so it reads large in
 * the top-left of the app; pass `animate` to drive the swarm.
 */
export function BrandMark({ animate = true }: BrandMarkProps) {
  return (
    <span className="flex items-center gap-2 text-lg">
      <LemniscateSwarm className="h-[2em] w-[2em] text-foreground" animate={animate} />
      <span className="font-semibold tracking-tight">{BRAND_NAME}</span>
    </span>
  );
}

import { renderToStaticMarkup } from 'react-dom/server';
import { describe, expect, it } from 'vitest';

import { BrandMark } from './BrandMark';

describe('BrandMark', () => {
  it('renders the wordmark in lowercase', () => {
    const html = renderToStaticMarkup(<BrandMark />);
    expect(html).toContain('>lemniscate<');
    expect(html).not.toContain('>Lemniscate<');
  });

  it('sizes the animated logo to twice the label font size (2em box)', () => {
    const html = renderToStaticMarkup(<BrandMark />);
    expect(html).toContain('h-[2em]');
    expect(html).toContain('w-[2em]');
  });

  it('sets the label font size on the lockup so the 2em mark scales with it', () => {
    const html = renderToStaticMarkup(<BrandMark />);
    expect(html).toContain('text-lg');
  });

  it('animates the swarm by default', () => {
    const html = renderToStaticMarkup(<BrandMark />);
    expect(html).toContain('animateMotion');
  });

  it('shows only the static mark (no swarm) when animate is false', () => {
    const html = renderToStaticMarkup(<BrandMark animate={false} />);
    expect(html).not.toContain('animateMotion');
    expect(html).toContain('h-[2em]');
  });
});

import { Link } from 'react-router-dom';

import { BrandMark } from '@/components/BrandMark';
import { NotificationBell } from '@/components/NotificationBell';
import { SettingsDialog } from '@/components/settings/SettingsDialog';
import { ThemeToggle } from '@/components/ThemeToggle';
import { useHasActiveProcesses } from '@/lib/queries/tasks';

/**
 * Top navigation bar: logo + app name on the left (links back to the
 * landing page), theme toggle and settings dialog on the right. The logo
 * animates only while a task is running or in review.
 */
export function TopNav() {
  const animate = useHasActiveProcesses();
  return (
    <header className="flex h-14 shrink-0 items-center justify-between border-b px-4">
      <Link to="/" aria-label="Go to landing page">
        <BrandMark animate={animate} />
      </Link>

      <div className="flex items-center gap-1">
        <NotificationBell />
        <ThemeToggle />
        <SettingsDialog />
      </div>
    </header>
  );
}

import { Loader2 } from 'lucide-react';
import { Link } from 'react-router-dom';

import { BrandMark } from '@/components/BrandMark';
import { ThemeToggle } from '@/components/ThemeToggle';
import { buttonVariants } from '@/components/ui/button';
import { useHasActiveProcesses } from '@/lib/queries/tasks';
import { useMe } from '@/lib/hooks';

function AuthAction() {
  const me = useMe();
  if (me.isPending) {
    return <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" aria-label="Loading" />;
  }
  if (me.data) {
    return (
      <Link to="/dashboard" className={buttonVariants({ size: 'sm' })}>
        Dashboard
      </Link>
    );
  }
  return (
    <Link to="/login" className={buttonVariants({ variant: 'outline', size: 'sm' })}>
      Log in
    </Link>
  );
}

/** Landing top bar: logo + name, session-aware auth action and theme toggle. */
export function LandingHeader() {
  const animate = useHasActiveProcesses();
  return (
    <header className="flex h-14 shrink-0 items-center justify-between border-b px-4">
      <BrandMark animate={animate} />
      <div className="flex items-center gap-2">
        <AuthAction />
        <ThemeToggle />
      </div>
    </header>
  );
}

